from __future__ import annotations

import dataclasses

from risk.types import VolSeries


def annualize(vol: VolSeries, periods_per_year: int = 252) -> VolSeries:
    """The series marked annualized; ValueError if it already is."""
    if vol.annualized:
        raise ValueError("volatility is already annualized")
    return dataclasses.replace(vol, annualized=True)

