"""PL-02 smoke: the pipeline runs end to end on the load_prices fake; shape only, no values."""

from __future__ import annotations

import pytest

from risk import vol_pipeline
from risk.types import Returns, VolSeries

pytestmark = pytest.mark.unit


@pytest.fixture
def fake_prices(monkeypatch, contract_fake):
    monkeypatch.setattr(
        vol_pipeline, "load_prices", contract_fake("mdata.load_prices").load_prices
    )


@pytest.mark.usefixtures("fake_prices")
def test_vol_series_runs_on_the_fake(contract_sample):
    dates = contract_sample("mdata.Prices")["dates"]
    vol = vol_pipeline.vol_series("prices.csv", window=2)
    assert isinstance(vol, VolSeries)
    assert isinstance(vol.returns, Returns)
    assert vol.annualized is True
    assert vol.window == 2
    assert vol.returns.tickers == ("AAPL", "MSFT")
    assert vol.returns.dates == tuple(dates[1:])
    assert set(vol.values) == {"AAPL", "MSFT"}
    assert all(len(vol.values[t]) == len(dates) - 1 for t in vol.values)
    assert all(vol.values[t][:2] == (None, None) for t in vol.values)


@pytest.mark.usefixtures("fake_prices")
def test_vol_series_narrows_tickers():
    vol = vol_pipeline.vol_series("prices.csv", window=2, tickers=["MSFT"])
    assert vol.returns.tickers == ("MSFT",)
    assert set(vol.values) == {"MSFT"}


@pytest.mark.usefixtures("fake_prices")
def test_vol_series_rejects_a_window_below_two():
    with pytest.raises(ValueError, match="window"):
        vol_pipeline.vol_series("prices.csv", window=1)

